### Component 3: Flow Generator - Coupling Flow Matching in Futhark

Implement complete CFM rectified flow generator in Futhark with Tensor Core optimization:

**Rectified Flow Mathematical Foundation:**
- Flow equation: dz/dt = v_θ(z_t, t, c) where z_t = t·z_1 + (1-t)·z_0
- Straight-line interpolation: no curved paths, direct noise-to-image
- Velocity field v_θ parameterized by neural network
- Time embedding: sinusoidal encoding concat with conditioning
- Loss function: L = E[||v_θ(z_t, t, c) - (z_1 - z_0)||²]

**Futhark Implementation:**
```futhark
-- File: src/flow_generator/rectified_flow.fut
type tensor2d = [][]f32
type tensor3d = [][][]f32
type tensor4d = [][][][]f32

-- Velocity network forward pass
let velocity_network [h][w][c] 
    (latent: [h][w][c]f32) 
    (time: f32) 
    (conditioning: []f32) 
    (weights: velocity_weights) : [h][w][c]f32 =
  let time_emb = sinusoidal_embedding time
  let cond_combined = concat time_emb conditioning
  -- UNet-style architecture with skip connections
  let encoder_features = encode_latent latent cond_combined weights.encoder
  let bottleneck = process_bottleneck encoder_features cond_combined weights.bottleneck
  let decoder_output = decode_features bottleneck encoder_features cond_combined weights.decoder
  in decoder_output

-- ODE solver: Euler method with adaptive step size
let flow_step [h][w][c] 
    (latent: [h][w][c]f32) 
    (t: f32) 
    (dt: f32) 
    (conditioning: []f32) 
    (weights: velocity_weights) : [h][w][c]f32 =
  let velocity = velocity_network latent t conditioning weights
  in map3 (\plane vel_plane -> 
       map2 (\row vel_row -> 
         map2 (\pixel vel -> pixel + dt * vel) row vel_row
       ) plane vel_plane
     ) latent velocity

-- Complete generation loop
let generate [steps] 
    (noise: tensor3d) 
    (conditioning: []f32) 
    (weights: velocity_weights) : tensor3d =
  let dt = 1.0 / f32.i64 steps
  let time_points = map (\i -> f32.i64 i * dt) (iota steps)
  in loop latent = noise for t in time_points do
       flow_step latent t dt conditioning weights

-- Tensor Core optimized matrix multiplication
let matmul_tc [n][m][k] (a: [n][m]f16) (b: [m][k]f16) : [n][k]f32 =
  map (\a_row ->
    map (\b_col ->
      f32.f16 (reduce (+) 0f16 (map2 (*) a_row b_col))
    ) (transpose b)
  ) a

-- Coupling mechanism for upsampling
let coupling_upsample [h][w][c] 
    (low_res: [h][w][c]f32) 
    (target_h: i64) 
    (target_w: i64) 
    (weights: coupling_weights) : tensor3d =
  let scale_h = f32.i64 target_h / f32.i64 h
  let scale_w = f32.i64 target_w / f32.i64 w
  -- Learned upsampling via transposed convolution
  let upsampled = transposed_conv2d low_res weights.upsample_kernel scale_h scale_w
  -- Refinement with coupling flow
  let refined = map3 (\plane y x ->
                  let local_context = extract_context upsampled y x 3
                  let flow_correction = coupling_flow local_context weights.coupling_net
                  in plane + flow_correction
                ) upsampled (iota target_h) (iota target_w)
  in refined
```

**Tensor Core Integration:**
```futhark
-- File: src/flow_generator/tensor_core_ops.fut
-- Utilize wmma intrinsics for matrix multiplication
entry matmul_16x16x16_tc [n][m][k] (a: [n][m]f16) (b: [m][k]f16) : [n][k]f32 =
  let tile_size = 16
  -- Tile matrices for Tensor Core processing
  let a_tiles = tile_matrix a tile_size tile_size
  let b_tiles = tile_matrix b tile_size tile_size
  -- Parallel Tensor Core execution
  let result_tiles = map2 (\a_tile_row b_tile_col ->
                      map2 (\a_tile b_tile ->
                        wmma_multiply a_tile b_tile
                      ) a_tile_row b_tile_col
                    ) a_tiles (transpose b_tiles)
  in untile_matrix result_tiles

-- Fused operations for memory efficiency
entry fused_conv_relu_tc [n][h][w][c_in][c_out] 
    (input: [n][h][w][c_in]f16) 
    (kernel: [c_out][c_in]f16)[2]
    (bias: [c_out]f16) : [n][h][w][c_out]f32 =
  map (\batch ->
    map2 (\y x ->
      map (\k_out ->
        let conv_sum = reduce (+) 0f16 (
          flatten (map2 (\k_in kernel_slice ->
            map2 (\ky kx ->
              let iy = y + ky - 1
              let ix = x + kx - 1
              in if iy >= 0 && iy < h && ix >= 0 && ix < w
                 then input[batch,iy,ix,k_in] * kernel_slice[ky,kx]
                 else 0f16
            ) (iota 3) (iota 3)
          ) (iota c_in) kernel[k_out])
        )
        let biased = conv_sum + bias[k_out]
        in f32.max 0f32 (f32.f16 biased)  -- ReLU activation
      ) (iota c_out)
    ) (iota h) (iota w)
  ) input
```

