```fsharp
// File: src/training/spiral_kernels.spi
open Spiral.Types
open Spiral.Cuda

// Forward pass kernel generator
let forward_pass_kernel (batch_size: int) (latent_dim: int) = cuda {
    // Text encoding forward
    let! text_encoded = ddl_encoder_forward text_tokens

    // Multi-lane bridge forward
    let! conditioned_latent = mhc_bridge_forward text_encoded

    // Flow matching forward
    let! flow_generated = rectified_flow_forward conditioned_latent noise time_steps

    // Upsampling forward
    let! upsampled = coupling_upsample_forward flow_generated

    // Refinement forward
    let! refined_output = bend_refiner_forward upsampled text_encoded

    return refined_output
}

// Backward pass kernel generator
let backward_pass_kernel (batch_size: int) = cuda {
    // Compute losses
    let! total_loss = compute_composite_loss target_image refined_output

    // Gradient computation - reverse order
    let! grad_refiner = bend_refiner_backward total_loss
    let! grad_upsampler = coupling_upsample_backward grad_refiner
    let! grad_flow = rectified_flow_backward grad_upsampler
    let! grad_bridge = mhc_bridge_backward grad_flow
    let! grad_encoder = ddl_encoder_backward grad_bridge

    return (grad_encoder, grad_bridge, grad_flow, grad_upsampler, grad_refiner)
}

// Loss function kernels
let flow_matching_loss (pred: Tensor) (target: Tensor) (time: float32) = cuda {
    // MSE loss between predicted velocity and target velocity
    let! diff = tensor_subtract target pred
    let! squared = tensor_multiply diff diff
    let! mean = tensor_reduce_mean squared
    return mean
}

let perceptual_loss (pred: Tensor) (target: Tensor) (vgg_features: VGGNet) = cuda {
    // Multi-scale perceptual loss
    let! pred_features = vgg_features.extract_features pred [|3; 8; 15; 22|]
    let! target_features = vgg_features.extract_features target [|3; 8; 15; 22|]

    let! layer_losses = map2 (fun p t -> 
        let! diff = tensor_subtract t p
        let! l2 = tensor_l2_norm diff
        return l2
    ) pred_features target_features

    let! total = reduce_sum layer_losses
    return total
}

let adversarial_loss (real: Tensor) (fake: Tensor) (discriminator: Discriminator) = cuda {
    // Hinge loss for discriminator
    let! d_real = discriminator.forward real
    let! d_fake = discriminator.forward fake

    let! loss_real = relu (1.0 - d_real) |> tensor_mean
    let! loss_fake = relu (1.0 + d_fake) |> tensor_mean

    return (loss_real + loss_fake)
}

// Optimizer kernel - AdamW
let adamw_update_kernel (learning_rate: float32) (beta1: float32) (beta2: float32) 
                        (weight_decay: float32) (epsilon: float32) (step: int) = cuda {
    // Bias correction
    let bias_correction1 = 1.0 - (powi beta1 step)
    let bias_correction2 = 1.0 - (powi beta2 step)

    // Update parameters
    let! updated_params = map3 (fun param grad (m, v) ->
        // Update biased first moment estimate
        let! m_new = beta1 * m + (1.0 - beta1) * grad

        // Update biased second moment estimate
        let! v_new = beta2 * v + (1.0 - beta2) * (grad * grad)

        // Compute bias-corrected estimates
        let! m_hat = m_new / bias_correction1
        let! v_hat = v_new / bias_correction2

        // Update parameters with weight decay
        let! param_new = param * (1.0 - learning_rate * weight_decay) - 
                        learning_rate * m_hat / (sqrt(v_hat) + epsilon)

        return (param_new, (m_new, v_new))
    ) parameters gradients momentum_estimates

    return updated_params
}

// Gradient accumulation kernel
let gradient_accumulation_kernel (num_accumulation_steps: int) = cuda {
    // Initialize accumulated gradients
    let! acc_grads = zero_gradients()

    // Accumulate over micro-batches
    for i in 0 .. num_accumulation_steps - 1 do
        let! micro_batch = get_micro_batch i
        let! loss = forward_pass micro_batch
        let! grads = backward_pass loss
        let! acc_grads = accumulate_gradients acc_grads grads

    // Average accumulated gradients
    let! avg_grads = scale_gradients acc_grads (1.0 / float32 num_accumulation_steps)

    return avg_grads
}

// Mixed precision training kernel
let mixed_precision_kernel () = cuda {
    use loss_scaler = GradScaler(init_scale=2.0^^16, growth_factor=2.0, backoff_factor=0.5)

    // Forward in FP16
    let! output = forward_pass_fp16 input
    let! loss = compute_loss output target

    // Scale loss for backward
    let! scaled_loss = loss_scaler.scale loss

    // Backward pass
    let! scaled_grads = backward_pass scaled_loss

    // Unscale gradients
    let! grads = loss_scaler.unscale scaled_grads

    // Check for inf/nan
    if has_inf_or_nan grads then
        loss_scaler.backoff()
        return None
    else
        // Update parameters
        let! updated = optimizer_step grads
        loss_scaler.grow()
        return Some updated
}

// Distributed training kernel (8× B200)
let distributed_training_kernel (world_size: int) (rank: int) = cuda {
    // Data parallelism across 8 GPUs
    let! local_batch = get_local_batch rank

    // Forward pass on local GPU
    let! local_output = forward_pass local_batch
    let! local_loss = compute_loss local_output local_batch.target

    // Backward pass
    let! local_grads = backward_pass local_loss

    // All-reduce gradients across GPUs using NCCL
    let! averaged_grads = nccl_allreduce local_grads world_size

    // Optimizer step on averaged gradients
    let! updated_params = optimizer_step averaged_grads

    // Broadcast updated parameters to all GPUs
    let! synced_params = nccl_broadcast updated_params root_rank=0

    return (local_loss, synced_params)
}
