        component = "encoder"
    elif rank < 6:
        # GPUs 3-5: Flow generation and upsampling
        component = "flow_upsample"
    else:
        # GPUs 6-7: Refinement
        component = "refiner"

    print(f"Rank {rank}: Assigned to {component} on {device}")

    # Setup NVLink peer access between GPUs
    for peer_rank in range(8):
        if peer_rank != rank:
            torch.cuda.device(rank).enable_peer_access(peer_rank)

