            loss,
            weights,
            device.index
        )

        # All-reduce gradients across 8 GPUs
        for param_name, grad in gradients.items():
            dist.all_reduce(grad, op=dist.ReduceOp.AVG)

        # Optimizer step (AdamW)
        training_lib.adamw_update_kernel(
            weights,
            gradients,
            learning_rate=learning_rate,
            step=step
        )

