    conditioned = encoder_lib.mhc_bridge(text_latent, weights["bridge"], device.index)

    edited_latent = flow_lib.rectified_flow_generate_i2i(
        noisy_latent,
        conditioned,
        num_steps=15,
        start_timestep=strength,  # Start from partially noised
        weights=weights["flow"],
        device=device.index
    )

    # If preservation mask provided, use Bend semantic editing
    if mask_array is not None:
        # Call Bend preserve_refine function
        bend_runtime.stdin.write(
            f"preserve_refine {source_array.tolist()} {edited_latent.tolist()} {mask_array.tolist()}\n".encode()
        )
        bend_runtime.stdin.flush()
        result = bend_runtime.stdout.readline()
        final_image = np.frombuffer(result, dtype=np.float32).reshape(source_image.size, source_image.size, 3)[3]
    else:
        # Standard refinement
        bend_runtime.stdin.write(
            f"refine_image {edited_latent.tolist()} {text_latent.tolist()}\n".encode()
        )
        bend_runtime.stdin.flush()
        result = bend_runtime.stdout.readline()
        final_image = np.frombuffer(result, dtype=np.float32).reshape(source_image.size, source_image.size, 3)[3]

    # Convert to PIL and return
    final_image = (final_image * 0.5 + 0.5).clip(0, 1)
    final_image = (final_image * 255).astype(np.uint8)
    pil_image = Image.fromarray(final_image)

    buffer = io.BytesIO()
    pil_image.save(buffer, format="PNG")
    return buffer.getvalue()

